mart_ellipses\";i:1;s:11:\"smart_marks\";i:1;s:16:\"smart_area_units\";i:1;s:10:\"smart_math\";i:0;s:15:\"smart_fractions\";i:0;s:14:\"smart_ordinals\";i:0;s:28:\"smart_ordinals_roman_numbers\";i:0;s:29:\"single_character_word_spacing\";i:0;s:12:\"dash_spacing\";i:0;s:16:\"fraction_spacing\";i:0;s:14:\"space_collapse\";i:0;s:26:\"french_punctuation_spacing\";i:0;s:30:\"numbered_abbreviations_spacing\";i:0;s:12:\"unit_spacing\";i:0;s:5:\"units\";s:17:\"hectare fortnight\";s:12:\"wrap_hyphens\";i:0;s:11:\"wrap_emails\";i:0;s:9:\"wrap_urls\";i:0;s:14:\"wrap_min_after\";i:3;s:14:\"prevent_widows\";i:0;s:16:\"widow_min_length\";i:5;s:14:\"widow_max_pull\";i:5;s:10:\"style_amps\";i:0;s:10:\"style_caps\";i:0;s:13:\"style_numbers\";i:0;s:25:\"style_hanging_punctuation\";i:0;s:20:\"style_initial_quotes\";i:0;s:18:\"initial_quote_tags\";s:39:\"p h1 h2 h3 h4 h5 h6 blockquote li dd dt\";s:17:\"style_css_include\";i:1;s:9:\"style_css\";s:835:\"/*\n * Styled sub- and superscripts.\n */\nsub, sup {\n  font-size: 75%;\n  line-height: 100%;\n}\n\nsup {\n  vertical-align: 60%;\n}\n\nsub {\n  vertical-align: -10%;\n}\n\n/*\n * Styled ampersands.\n */\n.amp {\n  font-family: Baskerville, \"Goudy Old Style\", Palatino, \"Book Antiqua\", \"Warnock Pro\", serif;\n  font-size: 1.1em;\n  font-style: italic;\n  font-weight: normal;\n  line-height: 1em;\n}\n\n/*\n * Words in caps.\n */\n.caps {\n  font-size: 90%;\n}\n\n/*\n * Styled initial quotes.\n */\n.dquo {\n  margin-left: -0.4em;\n}\n\n.quo {\n  margin-left: -0.2em;\n}\n\n/*\n * Hanging punctuation.\n */\n.pull-single {\n  margin-left: -0.15em;\n}\n\n.push-single {\n  margin-right: 0.15em;\n}\n\n.pull-double {\n  margin-left: -0.38em;\n}\n\n.push-double {\n  margin-right: 0.38em;\n}\n\n/*\n * Because formatting .numbers should consider your current font settings, we will not do it here.\n */\";}', 'on'),
