(15, 1, '2025-06-05 17:55:30', '2025-06-05 20:55:30', '<!-- wp:image {\"id\":16,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://receitas.test/wp-content/uploads/2025/06/Banner.jpg\" alt=\"\" class=\"wp-image-16\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":17,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"color\":\"#3d6d4a\",\"width\":\"10px\",\"radius\":\"100px\"}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"http://receitas.test/wp-content/uploads/2025/06/oleos-gorduras-acetos.png\" alt=\"\" class=\"has-border-color wp-image-17\" style=\"border-color:#3d6d4a;border-width:10px;border-radius:100px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Óleos</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":18,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"color\":\"#3d6d4a\",\"width\":\"10px\",\"radius\":\"100px\"}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"http://receitas.test/wp-content/uploads/2025/06/frutas-secas.png\" alt=\"\" class=\"has-border-color wp-image-18\" style=\"border-color:#3d6d4a;border-width:10px;border-radius:100px\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Cereais</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":19,\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"style\":{\"border\":{\"color\":\"#3d6d4a\",\"width\":\"10px\",\"radius\":\"100px\"}}} -->\n<figure class=\"wp-block-image size-full has-custom-border\"><img src=\"http://receitas.test/wp-content/uploads/2025/06/leite-e-ovos.png\" alt=\"\" class=\"has-border-color wp-image-19\" style=\"bord